"""Read the JSON build manifest generated by ``jobcomp``."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Tuple

SCHEMA_VERSION = 1
DEFAULT_MANIFEST = "croco_build.json"


class ConfigError(RuntimeError):
    """The build manifest is missing or does not match the schema."""


def _get(data: Mapping[str, Any], *keys: str) -> Any:
    value: Any = data
    for key in keys:
        if not isinstance(value, Mapping) or key not in value:
            raise ConfigError(f"missing manifest key: {'.'.join(keys)}")
        value = value[key]
    return value


def _strings(value: Any, name: str) -> Tuple[str, ...]:
    if not isinstance(value, list) or not all(
        isinstance(item, str) for item in value
    ):
        raise ConfigError(f"manifest key '{name}' must be a list of strings")
    return tuple(value)


def _string_map(value: Any, name: str) -> Mapping[str, str]:
    if not isinstance(value, Mapping) or not all(
        isinstance(key, str) and isinstance(item, str)
        for key, item in value.items()
    ):
        raise ConfigError(f"manifest key '{name}' must map strings to strings")
    return {str(key): str(item) for key, item in value.items()}


def _bool_map(value: Any, name: str) -> Mapping[str, bool]:
    if not isinstance(value, Mapping) or not all(
        isinstance(key, str) and isinstance(item, bool)
        for key, item in value.items()
    ):
        raise ConfigError(
            f"manifest key '{name}' must map strings to booleans"
        )
    return dict(value)


@dataclass(frozen=True)
class BuildSection:
    backend: str
    source_dir: Path
    scratch_dir: Path
    run_dir: Path
    agrif_dir: Path
    jobs: int
    copy_mode: str
    targets: Tuple[str, ...]
    tools: Tuple[str, ...]


@dataclass(frozen=True)
class ToolchainSection:
    os_name: str
    fc: str
    fc_invoked: str
    ldr: str
    mpif90: str
    cc: str
    make: str
    cpp: Tuple[str, ...]


@dataclass(frozen=True)
class FlagsSection:
    cppflags: Tuple[str, ...]
    fflags: Tuple[str, ...]
    fflags90: Tuple[str, ...]
    ldflags: Tuple[str, ...]
    cflags: Tuple[str, ...]
    defines: Tuple[str, ...]
    include_dirs: Tuple[str, ...]
    library_dirs: Tuple[str, ...]
    libraries: Tuple[str, ...]


@dataclass(frozen=True)
class SourcesSection:
    fixed: Tuple[str, ...]
    free: Tuple[str, ...]


@dataclass(frozen=True)
class CrocoBuildConfig:
    """Typed view of ``Compile/croco_build.json``."""

    path: Path
    schema_version: int
    generator: Mapping[str, str]
    build: BuildSection
    toolchain: ToolchainSection
    flags: FlagsSection
    features: Mapping[str, bool]
    sources: SourcesSection
    environment: Mapping[str, str]

    @classmethod
    def load(cls, path: Path) -> "CrocoBuildConfig":
        path = Path(path)
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except OSError as exc:
            raise ConfigError(f"cannot read build manifest {path}: {exc}")
        except json.JSONDecodeError as exc:
            raise ConfigError(f"invalid JSON in build manifest {path}: {exc}")

        if not isinstance(data, Mapping):
            raise ConfigError(f"build manifest {path} must contain an object")
        version = data.get("schema_version")
        if version != SCHEMA_VERSION:
            raise ConfigError(
                f"unsupported build manifest schema {version!r} in {path}; "
                f"expected {SCHEMA_VERSION}"
            )
        try:
            return cls(
                path=path,
                schema_version=version,
                generator=dict(_get(data, "generator")),
                build=BuildSection(
                    backend=str(_get(data, "build", "backend")),
                    source_dir=Path(_get(data, "build", "source_dir")),
                    scratch_dir=Path(_get(data, "build", "scratch_dir")),
                    run_dir=Path(_get(data, "build", "run_dir")),
                    agrif_dir=Path(_get(data, "build", "agrif_dir")),
                    jobs=int(_get(data, "build", "jobs")),
                    copy_mode=str(_get(data, "build", "copy_mode")),
                    targets=_strings(
                        _get(data, "build", "targets"), "build.targets"
                    ),
                    tools=_strings(
                        _get(data, "build", "tools"), "build.tools"
                    ),
                ),
                toolchain=ToolchainSection(
                    os_name=str(_get(data, "toolchain", "os")),
                    fc=str(_get(data, "toolchain", "fc")),
                    fc_invoked=str(_get(data, "toolchain", "fc_invoked")),
                    ldr=str(_get(data, "toolchain", "ldr")),
                    mpif90=str(_get(data, "toolchain", "mpif90")),
                    cc=str(_get(data, "toolchain", "cc")),
                    make=str(_get(data, "toolchain", "make")),
                    cpp=_strings(
                        _get(data, "toolchain", "cpp"), "toolchain.cpp"
                    ),
                ),
                flags=FlagsSection(
                    cppflags=_strings(
                        _get(data, "flags", "cppflags"), "flags.cppflags"
                    ),
                    fflags=_strings(
                        _get(data, "flags", "fflags"), "flags.fflags"
                    ),
                    fflags90=_strings(
                        _get(data, "flags", "fflags90"), "flags.fflags90"
                    ),
                    ldflags=_strings(
                        _get(data, "flags", "ldflags"), "flags.ldflags"
                    ),
                    cflags=_strings(
                        _get(data, "flags", "cflags"), "flags.cflags"
                    ),
                    defines=_strings(
                        _get(data, "flags", "defines"), "flags.defines"
                    ),
                    include_dirs=_strings(
                        _get(data, "flags", "include_dirs"),
                        "flags.include_dirs",
                    ),
                    library_dirs=_strings(
                        _get(data, "flags", "library_dirs"),
                        "flags.library_dirs",
                    ),
                    libraries=_strings(
                        _get(data, "flags", "libraries"),
                        "flags.libraries",
                    ),
                ),
                features=_bool_map(
                    _get(data, "features"), "features"
                ),
                sources=SourcesSection(
                    fixed=_strings(
                        _get(data, "sources", "F"), "sources.F"
                    ),
                    free=_strings(
                        _get(data, "sources", "F90"), "sources.F90"
                    ),
                ),
                environment=_string_map(
                    _get(data, "environment"), "environment"
                ),
            )
        except (TypeError, ValueError) as exc:
            raise ConfigError(f"invalid build manifest {path}: {exc}")
